period_src='''from collections import Counter

def transform(grid):
    """Continue a repeated foreground pattern to the right, marking new cells 1."""
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [list(row) for row in grid]
    for r, row in enumerate(grid):
        fg = [c for c, v in enumerate(row) if v != bg]
        if not fg:
            continue
        end = fg[-1]
        if end == w - 1:
            continue
        best = None
        # Choose the longest suffix ending at the last foreground cell that
        # has a short exact period. At least two full periods are required.
        for p in range(1, min(8, (end + 1) // 2) + 1):
            for start in range(0, end - 2*p + 2):
                n = end - start + 1
                if n < 2*p:
                    continue
                if all(row[c] == row[start + (c-start) % p] for c in range(start, end + 1)):
                    cand = (n, p, start)
                    if best is None or cand[0] > best[0] or (cand[0] == best[0] and p < best[1]):
                        best = cand
        # A long solid terminal run is a clear period-1 continuation.
        run = 1
        while end-run >= 0 and row[end-run] == row[end]:
            run += 1
        if run >= 5 and (best is None or run > best[0]):
            best = (run, 1, end-run+1)
        if best is None:
            continue
        _, p, start = best
        for c in range(end+1, w):
            expected = row[start + (c-start) % p]
            if expected != bg:
                out[r][c] = 1
    return out
'''
